import random
G = (9, 9)
MOVES = {0: (1, 0), 1: (0, 1), 2: (-1, 0), 3: (0, -1)}


def expert(s):
    x, y = s
    if x < G[0]:
        return 0
    if y < G[1]:
        return 1
    return 0


def step(s, a, slip, rng):
    if rng.random() < slip:
        a = rng.randrange(4)
    dx, dy = MOVES[a]
    return (min(max(s[0] + dx, 0), 9), min(max(s[1] + dy, 0), 9))


def rollout(policy, slip, rng, limit=40):
    s = (0, 0)
    for _ in range(limit):
        if s == G:
            return True
        s = step(s, policy(s), slip, rng)
    return s == G


def demos(n, slip, seed):
    rng = random.Random(seed)
    D = {}
    for _ in range(n):
        s = (0, 0)
        for _ in range(40):
            if s == G:
                break
            a = expert(s)
            D[s] = a
            s = step(s, a, slip, rng)
    return D


def make_bc(D):
    def pi(s):
        if s in D:
            return D[s]
        n = min(D, key=lambda k: abs(k[0] - s[0]) + abs(k[1] - s[1]))
        return D[n]
    return pi


def success(pi, slip, N=2000):
    rng = random.Random(1)
    return sum(rollout(pi, slip, rng) for _ in range(N)) / N


for ds in (0.0, 0.2):
    D = demos(5, ds, 0)
    print(f"시연 5번(시연 때 미끄러짐 {ds}) 본 칸 {len(D)}/100")
    print("  전문가 성공률 %.2f" % success(expert, 0.2), "| 모방(BC) 성공률 %.2f" % success(make_bc(D), 0.2))
